import SwiftUI
#if canImport(UIKit)
import UIKit
#endif

/// A REAL server-rendered hole image, BAKED for the design snapshot — gid31669 hole 4 (Par 5, 518.8 m,
/// dogleg). OB flood-filled to BLACK, and **brightened + saturated** (PIL ImageEnhance Color×1.42 /
/// Brightness×1.12 / Contrast×1.16) so the fairway reads vibrant/high-contrast like Garmin's (design
/// review: the raw render was too dark/muddy). Overlay 720×1120 at ppm≈1.442; px are the real prep route.
public enum WatchHoleMapSample {
    static let imageSize = CGSize(width: 720, height: 1120)
    static let ppm: CGFloat = 1.4419
    static let youPx = CGPoint(x: 504, y: 702)           // 2nd shot lie — 200 m from tee
    static let apexPx = CGPoint(x: 556, y: 562)          // dogleg apex (303 m)
    static let layupPx = CGPoint(x: 506, y: 403)         // lay-up target (419 m ≈ 100 m short)
    static let greenCtrlPx = CGPoint(x: 498, y: 375)     // control for lay-up→green dashed curve
    static let pinPx = CGPoint(x: 435, y: 279)           // green centre / pin (518.8 m)
    static let lastShotPx = CGPoint(x: 435, y: 981)      // tee-shot origin

    #if canImport(UIKit)
    static let image: UIImage? = Data(base64Encoded: jpegBase64).flatMap(UIImage.init(data:))
    #endif

    static let jpegBase64 = ""
}
